package com.alertBadOffers;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("AlertBadOffers")
public interface AlertBadOffersConfig extends Config
{
	@ConfigItem(
			keyName = "customGeDeviationThreshold",
			name = "Price Deviation Warning (%)",
			description = "Triggers a custom warning panel if your offer price differs from the guide price by more than this percentage.",
			position = 1
	)
	default int customGeDeviationThreshold()
	{
		return 10; // Default to a 10% tolerance limit
	}
	@ConfigItem(
			keyName = "minGeDeviationGpThreshold",
			name = "Minimum GP Deviation",
			description = "The minimum absolute GP difference required to trigger the warning banner.",
			position = 2
	)
	default int minGeDeviationGpThreshold()
	{
		return 100000; // Default to 100,000 gp (100k) minimum difference
	}

	@ConfigItem(
			keyName = "maxGeDeviationGpThreshold",
			name = "Maximum GP Deviation",
			description = "The absolute maximum GP difference allowed. Any offer exceeding this flat cash difference will be flagged instantly, regardless of percentages.",
			position = 3
	)
	default int maxGeDeviationGpThreshold()
	{
		return 10000000; // Default to 10M GP limit
	}

	@ConfigItem(
			keyName = "useRealTimePrices",
			name = "Use Real-Time 1-Hour Average",
			description = "Use the live OSRS Wiki 1-hour average prices for calculations instead of the in-game GE guide price.",
			position = 4
	)
	default boolean useRealTimePrices()
	{
		return false;
	}
}

package com.alertBadOffers;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Alert Bad Offers"
)
public class AlertBadOffersPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private AlertBadOffersConfig config;

	@Inject
	private OverlayManager overlayManager;
	@Inject
	private GeDeviationOverlay geDeviationOverlay;

	@Inject
	private WikiPriceService wikiPriceService;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(geDeviationOverlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(geDeviationOverlay);
		GeDeviationOverlay.lastAttemptedOfferHash = 0;
		wikiPriceService.clearCache();
	}

	@Provides
	AlertBadOffersConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AlertBadOffersConfig.class);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = event.getMenuOption();
		if (option != null && option.equalsIgnoreCase("Confirm"))
		{
			Widget guidePriceWidget = client.getWidget(465, 28);
			Widget parentWidget = client.getWidget(465, 26);

			if (guidePriceWidget == null || parentWidget == null) return;

			Widget[] structuralChildren = parentWidget.getChildren();
			if (structuralChildren == null || structuralChildren.length <= 41 || structuralChildren[41] == null || structuralChildren[23] == null) return;

			int itemId = structuralChildren[23].getItemId();
			if (itemId <= 0) return;

			// DETERMINE TARGET BASE PRICE
			long targetBasePrice = 0;
			if (config.useRealTimePrices())
			{
				targetBasePrice = wikiPriceService.getPrice(itemId);
			}
			if (targetBasePrice <= 0)
			{
				targetBasePrice = GeDeviationOverlay.parseLongSafely(guidePriceWidget.getText());
			}

			long offerPrice = GeDeviationOverlay.parseLongSafely(structuralChildren[41].getText());
			String quantityText = structuralChildren[34] != null ? structuralChildren[34].getText() : "1";
			long quantity = GeDeviationOverlay.parseLongSafely(quantityText);
			if (quantity <= 0) quantity = 1;

			if (targetBasePrice <= 0 || offerPrice <= 0) return;

			long gpDifference = Math.abs(offerPrice - targetBasePrice);
			double deviation = ((double) gpDifference / targetBasePrice) * 100;
			long totalGpDifference = gpDifference * quantity;

			// MULTI-GUARD FILTER EVALUATION
			boolean isPercentageViolation = deviation > config.customGeDeviationThreshold() && totalGpDifference >= config.minGeDeviationGpThreshold();
			boolean isMaxGpViolation = totalGpDifference >= config.maxGeDeviationGpThreshold();

			if (isPercentageViolation || isMaxGpViolation) {
				int currentOfferHash = java.util.Objects.hash(itemId, targetBasePrice, offerPrice, quantityText);

				if (currentOfferHash != GeDeviationOverlay.lastAttemptedOfferHash)
				{
					event.consume();
					GeDeviationOverlay.lastAttemptedOfferHash = currentOfferHash;
				}
			}
		}
	}

}

package com.alertBadOffers;

import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;


public class GeDeviationOverlay extends Overlay
{
    private final Client client;
    private final AlertBadOffersConfig config;
    private final WikiPriceService wikiPriceService;

    public static int lastAttemptedOfferHash = 0;

    @Inject
    public GeDeviationOverlay(Client client, AlertBadOffersConfig config, WikiPriceService wikiPriceService)
    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        this.client = client;
        this.config = config;
        this.wikiPriceService = wikiPriceService;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        Widget headerWidget = client.getWidget(465, 2);
        if (headerWidget == null || headerWidget.isHidden()) return null;

        Widget[] headerChildren = headerWidget.getChildren();
        if (headerChildren == null || headerChildren.length < 2 || headerChildren[1] == null) return null;

        if (!headerChildren[1].getText().contains("Set up offer")) {
            lastAttemptedOfferHash = 0; // Possible cleanup after last offer was made
            return null;
        }

        Widget guidePriceWidget = client.getWidget(465, 28);
        if (guidePriceWidget == null || guidePriceWidget.isHidden()) return null;


        Widget parentWidget = client.getWidget(465, 26);
        if (parentWidget == null || parentWidget.isHidden()) return null;

        Widget[] structuralChildren = parentWidget.getChildren();
        if (structuralChildren == null || structuralChildren.length <= 41 || structuralChildren[41] == null || structuralChildren[23] == null) return null;

        int itemId = structuralChildren[23].getItemId();
        if (itemId <= 0) return null;

        // DETERMINE TARGET BASE PRICE
        long targetBasePrice = 0;
        if (config.useRealTimePrices())
        {
            targetBasePrice = wikiPriceService.getPrice(itemId);
        }

        // Fall back to normal GE price if config toggle is off OR if Wiki API hasn't resolved yet
        if (targetBasePrice <= 0)
        {
            targetBasePrice = parseLongSafely(guidePriceWidget.getText());
        }

        if (targetBasePrice <= 0) return null;

        long offerPrice = parseLongSafely(structuralChildren[41].getText());
        String quantityText = structuralChildren[34] != null ? structuralChildren[34].getText() : "1";
        long quantity = parseLongSafely(quantityText);
        if (quantity <= 0) quantity = 1;
        if (offerPrice <= 0) return null;

        long gpDifference = Math.abs(offerPrice - targetBasePrice);
        double deviation = ((double) gpDifference / targetBasePrice) * 100;
        long totalGpDifference = gpDifference * quantity;

        int currentOfferHash = java.util.Objects.hash(itemId, targetBasePrice, offerPrice, quantityText);
        if (currentOfferHash != lastAttemptedOfferHash)
        {
            lastAttemptedOfferHash = 0;
        }

        // EVALUATE NEW SLIDER BOUNDS
        boolean isPercentageViolation = deviation > config.customGeDeviationThreshold() && totalGpDifference >= config.minGeDeviationGpThreshold();
        boolean isMaxGpViolation = totalGpDifference >= config.maxGeDeviationGpThreshold();

        if (isPercentageViolation || isMaxGpViolation)
        {
            boolean isFirstClickBlocked = (currentOfferHash == lastAttemptedOfferHash);

            // 1. Prepare lines dynamically
            String line1 = "";
            String line2;

            if (config.useRealTimePrices())
            {
                line1 = String.format("1-Hour Average Mid price is: %,d GP", targetBasePrice);
            }

            if (isFirstClickBlocked)
            {
                line2 = isMaxGpViolation && !isPercentageViolation
                        ? String.format("⚠️ Confirm again to force submit (Deviates +%,d GP)", totalGpDifference)
                        : String.format("⚠️ Confirm again to force submit (Deviates %.1f%%)", deviation);
            }
            else
            {
                line2 = isMaxGpViolation && !isPercentageViolation
                        ? String.format("⚠️ Warning: Loss exceeds Max Limit (+%,d GP)!", totalGpDifference)
                        : String.format("⚠️ Warning: Price deviates by %.1f%%!", deviation);
            }

            Color accentColor = (isFirstClickBlocked) ? new Color(255, 152, 0) : new Color(239, 83, 80);

            graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_GASP);
            Font originalFont = graphics.getFont();
            Font warningFont = new Font("Dialog", Font.BOLD, 12);
            graphics.setFont(warningFont);

            FontMetrics metrics = graphics.getFontMetrics(warningFont);

            // 2. Calculate dimension metrics considering both lines
            boolean hasTwoLines = !line1.isEmpty();
            int textWidth = Math.max(metrics.stringWidth(line2), hasTwoLines ? metrics.stringWidth(line1) : 0);
            int lineHeight = metrics.getHeight();
            int textHeight = hasTwoLines ? (lineHeight * 2) + 2 : lineHeight; // Added 2px line spacing padding

            int paddingX = 14;
            int paddingY = 8;
            int boxWidth = textWidth + (paddingX * 2);
            int boxHeight = textHeight + (paddingY * 2);

            int x = parentWidget.getCanvasLocation().getX() + (parentWidget.getWidth() / 2) - (boxWidth / 2);
            // Move the box up slightly more if it has two lines to prevent overlap with buttons
            int y = parentWidget.getCanvasLocation().getY() + parentWidget.getHeight() - (hasTwoLines ? 90 : 74);

            graphics.setColor(new Color(25, 25, 25, 230));
            graphics.fillRect(x, y, boxWidth, boxHeight);

            graphics.setColor(new Color(accentColor.getRed(), accentColor.getGreen(), accentColor.getBlue(), 160));
            graphics.drawRect(x, y, boxWidth, boxHeight);

            graphics.setColor(accentColor);
            int currentY = y + paddingY + metrics.getAscent();

            if (hasTwoLines)
            {
                int line1X = x + (boxWidth / 2) - (metrics.stringWidth(line1) / 2);
                graphics.setColor(Color.GRAY);
                graphics.drawString(line1, line1X, currentY);
                currentY += lineHeight + 2; // Advance cursor to next line space
            }

            int line2X = x + (boxWidth / 2) - (metrics.stringWidth(line2) / 2);
            graphics.setColor(accentColor);
            graphics.drawString(line2, line2X, currentY);

            graphics.setFont(originalFont);
        }

        return null;
    }

    public static long parseLongSafely(String text)
    {
        if (text == null) return 0;
        try
        {
            String cleanText = text.replaceAll("[^0-9]", "");
            return cleanText.isEmpty() ? 0 : Long.parseLong(cleanText);
        }
        catch (NumberFormatException e)
        {
            return 0;
        }
    }
}

package com.alertBadOffers;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStreamReader;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.annotation.Nonnull;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

@Slf4j
@Singleton
public class WikiPriceService
{
    private static final String API_URL = "https://prices.runescape.wiki/api/v1/osrs/1h";
    private static final int CACHE_DURATION_MINUTES = 5;

    private final OkHttpClient httpClient;
    private final Gson gson;

    private final Map<Integer, Long> priceCache = new HashMap<>();
    private Instant cacheExpiry = Instant.MIN;
    private boolean isFetching = false;

    @Inject
    public WikiPriceService(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    /**
     * Gets the 1-hour average price for an item.
     * Returns 0 if data isn't loaded yet or if the item isn't in the API response.
     */
    public long getPrice(int itemId)
    {
        if (Instant.now().isAfter(cacheExpiry))
        {
            fetchPrices();
        }
        return priceCache.getOrDefault(itemId, 0L);
    }

    private synchronized void fetchPrices()
    {
        if (isFetching) return;
        isFetching = true;

        priceCache.clear();

        HttpUrl url = HttpUrl.parse(API_URL);
        if (url == null)
        {
            log.error("Failed to parse Wiki API URL: {}", API_URL);
            isFetching = false;
            return;
        }

        Request request = new Request.Builder()
                .url(url)
                .header("User-Agent", "AlertBadOffers-RuneLitePlugin")
                .build();

        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(@Nonnull Call call, @Nonnull IOException e)
            {
                log.error("Failed to fetch OSRS Wiki real-time 1h prices", e);
                isFetching = false;
                cacheExpiry = Instant.now().plusSeconds(30);
            }

            @Override
            public void onResponse(@Nonnull Call call, @Nonnull Response response)
            {
                try (Response r = response)
                {
                    if (!r.isSuccessful() || r.body() == null)
                    {
                        isFetching = false;
                        cacheExpiry = Instant.now().plusSeconds(30);
                        return;
                    }

                    JsonObject root = gson.fromJson(new InputStreamReader(r.body().byteStream()), JsonObject.class);
                    if (root != null && root.has("data"))
                    {
                        JsonObject data = root.getAsJsonObject("data");
                        for (Map.Entry<String, JsonElement> entry : data.entrySet())
                        {
                            try
                            {
                                int id = Integer.parseInt(entry.getKey());
                                JsonObject fields = entry.getValue().getAsJsonObject();

                                // Call the clean, extracted helper method
                                long midPrice = calculateMidPrice(fields);

                                if (midPrice > 0)
                                {
                                    priceCache.put(id, midPrice);
                                }
                            }
                            catch (Exception ignored) {}
                        }
                    }
                    cacheExpiry = Instant.now().plus(CACHE_DURATION_MINUTES, java.time.temporal.ChronoUnit.MINUTES);
                }
                catch (Exception e)
                {
                    log.error("Error parsing wiki prices JSON", e);
                }
                finally
                {
                    isFetching = false;
                }
            }

            private long calculateMidPrice(JsonObject fields)
            {
                long avgHigh = fields.has("avgHighPrice") && !fields.get("avgHighPrice").isJsonNull() ? fields.get("avgHighPrice").getAsLong() : 0;
                long avgLow = fields.has("avgLowPrice") && !fields.get("avgLowPrice").isJsonNull() ? fields.get("avgLowPrice").getAsLong() : 0;

                if (avgHigh > 0 && avgLow > 0)
                {
                    return (avgHigh + avgLow) / 2;
                }
                else if (avgHigh > 0)
                {
                    return avgHigh;
                }
                else if (avgLow > 0)
                {
                    return avgLow;
                }

                return 0;
            }
        });
    }

    public void clearCache()
    {
        priceCache.clear();
        cacheExpiry = Instant.MIN;
    }
}

